window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[144]={"id":"144","numero":144,"titre":"Deuil normal et pathologique","objectifs":[{"id":"144-1","rang":"A","rubrique":"Définition","titre":"Connaître les caractéristiques d’un deuil normal et pathologique","contenu":"<p>Le <strong><span class=\"kw-def\">deuil</span></strong> désigne l’ensemble des <span class=\"kw-clinique\">réactions émotionnelles, cognitives et comportementales</span> face au décès d’une personne proche. C’est une réaction <strong>« normale »</strong> pour la majorité des personnes. Ces réactions dépendent du <span class=\"kw-etio\">contexte socio-culturel</span> : la douleur vécue par la personne endeuillée varie selon <span class=\"kw-clinique\">les</span> valeurs, les habitudes de vie et les principes d’un groupe ou d’une société.</p>\n\n      <p><strong><span class=\"kw-clinique\">Les</span> 4 phases du deuil normal</strong> — réactions émotionnelles pouvant être entremêlées ou simultanées :</p>\n      <table >\n        <thead><tr><th>Phase</th><th>Sémiologie</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">1 · Choc de la perte</span></td><td><span class=\"kw-clinique\">Abattement</span> ; <span class=\"kw-clinique\">état de sidération affective</span> (± symptômes dissociatifs)</td></tr>\n          <tr><td><span class=\"kw-def\">2 · Sentiment d’absence</span></td><td>Lié à l’état de manque du défunt : <span class=\"kw-clinique\">angoisse</span>, <span class=\"kw-clinique\">colère</span>, <span class=\"kw-clinique\">désespoir</span>, <span class=\"kw-clinique\">culpabilité</span></td></tr>\n          <tr><td><span class=\"kw-def\">3 · Tristesse</span></td><td><span class=\"kw-clinique\">Tristesse</span></td></tr>\n          <tr><td><span class=\"kw-def\">4 · Réorganisation</span></td><td>Acceptation de la réalité de la perte ; adaptation à une vie quotidienne réinvestie dans un monde où le défunt est absent</td></tr>\n        </tbody>\n      </table>\n\n      <p><strong><span class=\"kw-def\">Deuil normal</span></strong> : processus évoluant généralement vers l’<strong>apaisement</strong>, d’une durée moyenne de <span class=\"kw-chiffre\">2 à 3 mois</span>. Cette durée dépend du lien d’attachement avec le défunt, de l’âge du défunt et des circonstances du décès.</p>\n\n      <p><strong><span class=\"kw-def\">Deuil pathologique</span></strong> — quatre formes :</p>\n      <ul>\n        <li><strong>Deuil prolongé</strong> (détaillé ci-dessous).</li>\n        <li><strong><span class=\"kw-etio\">Épisode dépressif caractérisé</span></strong> : trouble psychiatrique le <strong>plus fréquent</strong> en contexte de deuil.</li>\n        <li><strong>Troubles anxieux</strong> : en particulier le <span class=\"kw-etio\">trouble anxieux généralisé</span>.</li>\n        <li><strong><span class=\"kw-etio\">TSPT</span></strong> : surtout si le décès ou l’<span class=\"kw-def\">annonce</span> du décès a été <strong>brutal</strong> (caractère traumatique).</li>\n      </ul>\n      <p>Le deuil est par ailleurs un <span class=\"kw-etio\">facteur de décompensation</span> de tous <span class=\"kw-clinique\">les</span> troubles psychiatriques préexistants et des usages de substance.</p>\n\n      <div class=\"callout callout-danger\"><strong>Risque suicidaire.</strong> Le <span class=\"kw-alerte\">risque de suicide</span> est fortement augmenté dans le deuil — surtout dans <span class=\"kw-clinique\">les</span> <strong>quelques jours qui suivent le décès</strong> (parfois avec l’intention « d’aller rejoindre le défunt »). Durant la <span class=\"kw-chiffre\">1ʳᵉ semaine</span> du deuil, il est multiplié par <span class=\"kw-chiffre\">&gt; ×50</span> chez les hommes et par <span class=\"kw-chiffre\">×10</span> chez les femmes.</div>\n\n      <div class=\"callout callout-info\"><strong>Piège EDN.</strong> Le deuil n’entraîne <strong>pas</strong> de <span class=\"kw-alerte\">trouble de l’adaptation</span> — on parle de <span class=\"kw-def\">deuil pathologique</span>.</div>\n\n      <p><strong>Le deuil prolongé</strong></p>\n      <table >\n        <thead><tr><th>Item</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Définition</span></td><td>Non-<span class=\"kw-clinique\">évolution</span> du processus de deuil vers la phase de réorganisation ; persistance d’<span class=\"kw-clinique\">altérations comportementales, émotionnelles et cognitives</span> ; <span class=\"kw-alerte\">limitation du fonctionnement social</span> ; <span class=\"kw-alerte\">incapacité fonctionnelle importante</span></td></tr>\n          <tr><td>Quand ?</td><td>Sujet ayant fait l’expérience du décès d’une personne proche <span class=\"kw-chiffre\">≥ 12 mois</span> auparavant</td></tr>\n          <tr><td>Manifestations</td><td>Symptômes cliniquement significatifs, en contradiction avec <span class=\"kw-clinique\">les</span> normes adaptées à la culture, la religion et l’âge :<br><strong>Manque :</strong> <span class=\"kw-clinique\">manque intense</span> ; préoccupation à propos du défunt ou des circonstances du décès<br><strong><span class=\"kw-alerte\">Détresse</span> réactionnelle :</strong> <span class=\"kw-clinique\">difficulté marquée à accepter le décès</span> ; <span class=\"kw-clinique\">incrédulité par rapport à la perte</span> ; <span class=\"kw-clinique\">évitement de tout ce qui rappelle la perte</span><br><strong><span class=\"kw-alerte\">Rupture</span> sociale / identitaire :</strong> <span class=\"kw-clinique\">difficulté à faire confiance à autrui</span> depuis le décès ; <span class=\"kw-clinique\">sentiment que la vie n’a plus de sens</span> ; <span class=\"kw-alerte\">désir de mourir afin d’être avec le défunt</span></td></tr>\n          <tr><td>Fréquence</td><td>Symptômes présents <strong>pratiquement tous <span class=\"kw-clinique\">les</span> jours</strong></td></tr>\n          <tr><td>Durée</td><td><strong>Adulte :</strong> <span class=\"kw-chiffre\">&gt; 12 mois</span> ; <strong>Enfant :</strong> <span class=\"kw-chiffre\">&gt; 6 mois</span></td></tr>\n        </tbody>\n      </table>\n\n      <p><strong>Deuil normal <span class=\"kw-bio\">vs</span> <span class=\"kw-etio\">épisode dépressif caractérisé</span></strong> — l’EDC en contexte de deuil est similaire à un EDC survenant hors deuil : même <span class=\"kw-def\">pronostic</span>, même durée d’épisode, mêmes <span class=\"kw-def\">comorbidités</span>, même réponse aux traitements, mêmes facteurs de risque (<span class=\"kw-etio\">antécédents familiaux</span> et personnels de troubles psychiatriques, troubles de l’humeur en particulier).</p>\n      <table >\n        <thead><tr><th>Critère</th><th>Deuil normal</th><th><span class=\"kw-etio\">Épisode dépressif caractérisé</span></th></tr></thead>\n        <tbody>\n          <tr><td>Affect prédominant</td><td>Sentiment de <span class=\"kw-clinique\">vide</span> et de <span class=\"kw-clinique\">perte</span>, lié à l’état de manque du défunt</td><td><span class=\"kw-clinique\">Humeur dépressive persistante</span></td></tr>\n          <tr><td>Émotions négatives</td><td>Diminuent d’intensité avec le temps ; surviennent par <strong>vagues</strong> associées à des pensées ou souvenirs du défunt</td><td><strong>Intenses</strong>, avec une <span class=\"kw-alerte\">douleur morale majeure et persistante</span>, non liée à des pensées spécifiques</td></tr>\n          <tr><td>Émotions positives</td><td>La douleur peut être accompagnée d’<span class=\"kw-clinique\">émotions positives</span> et d’<span class=\"kw-clinique\">humour</span></td><td><span class=\"kw-clinique\">Anhédonie</span> : incapacité à anticiper la joie ou le plaisir</td></tr>\n          <tr><td>Pensées</td><td>Préoccupations et souvenirs concernant la personne décédée</td><td><span class=\"kw-clinique\">Ruminations</span> autocritiques, fatalistes, culpabilisatrices, pessimistes</td></tr>\n          <tr><td>Estime de soi</td><td>Généralement <strong>préservée</strong></td><td><span class=\"kw-alerte\">Faible voire effondrée</span> : sentiments de dévalorisation et de dégoût de soi</td></tr>\n          <tr><td>Idées de suicide</td><td>Si présentes : idée de <strong>rejoindre le défunt</strong></td><td>Associées au sentiment de dévalorisation, d’indignité ou d’incapacité à faire face à la douleur</td></tr>\n        </tbody>\n      </table>\n\n      <p><strong>Spécificités du deuil périnatal</strong></p>\n      <p>La perte d’un fœtus ou d’un nouveau-né est un <strong>deuil à part entière</strong> : aucune perte d’un bébé n’est à minimiser, quelles que soient <span class=\"kw-clinique\">les</span> modalités du décès ou la durée de vie partagée. Elle renvoie les parents aux mêmes problématiques que la perte d’un enfant plus âgé et est souvent décrite comme « l’événement le plus traumatique qui soit » : annihilation de l’avenir rêvé, <span class=\"kw-alerte\">rupture</span> dans l’ordre générationnel, <span class=\"kw-alerte\">effraction du sentiment de compétence parentale</span>.</p>\n      <table >\n        <thead><tr><th>Dimension</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td>Difficultés spécifiques</td><td>Collusion des temps du naître et du mourir ; perte du statut de parent en devenir (<span class=\"kw-clinique\">sentiment de faillite</span>) ; impossibilité de la rencontre si décès in utero (<span class=\"kw-alerte\">blessure narcissique</span>, honte, culpabilité) ; <span class=\"kw-clinique\">sentiment d’irréalité</span> ; crainte d’une future <span class=\"kw-ci\">grossesse</span> ; <span class=\"kw-alerte\">intensité du sentiment de culpabilité</span> (surtout étiologies génétiques et malformatives) ; sentiment d’incompréhension par l’entourage</td></tr>\n          <tr><td>Vécu selon <span class=\"kw-clinique\">les</span> circonstances</td><td><strong>Décès d’un jumeau :</strong> sentiments contradictoires de joie et de tristesse, d’élan de vie et de mort<br><strong>Fausse couche / décès inopiné :</strong> aucun temps de préparation psychique<br><strong>IVG / IMG :</strong> ambivalence intense entre <span class=\"kw-clinique\">soulagement</span> et <span class=\"kw-clinique\">culpabilité</span> ; peur d’être jugés ; conflits possibles dans le couple ou avec l’entourage</td></tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 66 — Trouble dépressif · 353 — Risque et conduite suicidaire</em></p>","frequence":2},{"id":"144-2","rang":"B","rubrique":"Étiologies","titre":"Connaître les facteurs de risque de complications du deuil","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-etio\">facteurs de risque de deuil pathologique</span> (complications du deuil) sont régulièrement tombés à l’EDN. Ils se répartissent en <strong>trois catégories</strong>.</p>\n      <table >\n        <thead><tr><th>Catégorie</th><th><span class=\"kw-def\">Facteurs de risque</span></th></tr></thead>\n        <tbody>\n          <tr><td>Liés au <strong>défunt</strong></td><td><span class=\"kw-etio\">Mort d’une personne plus jeune</span> ; <span class=\"kw-etio\">décès du conjoint ou de l’enfant</span></td></tr>\n          <tr><td>Liés aux <strong>circonstances du décès</strong></td><td><span class=\"kw-etio\">Mort par suicide</span> ; <span class=\"kw-etio\">mort soudaine, inattendue, violente</span></td></tr>\n          <tr><td>Liés à l’<strong>endeuillé</strong></td><td><span class=\"kw-etio\">Âge jeune</span>, <span class=\"kw-etio\">femme</span> ; <span class=\"kw-etio\">relation d’attachement</span> avec le défunt ; <span class=\"kw-etio\">répétition de deuil</span> ; <span class=\"kw-etio\">antécédents personnels de trouble psychiatrique</span>, stratégie d’ajustement au stress réduite ; <span class=\"kw-clinique\">sentiment de culpabilité</span>, manque de compréhension de la situation ; <span class=\"kw-etio\">manque de soutien social</span>, <span class=\"kw-etio\">précarité sociale</span>, <span class=\"kw-etio\">absence de rituels de deuil</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Distracteur EDN.</strong> Un <strong>deuil récent</strong> n’est <strong>pas</strong> un <span class=\"kw-def\">facteur de risque</span> de deuil pathologique — piège classique de QCM.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 353 — Risque et conduite suicidaire</em></p>","frequence":4},{"id":"144-3","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes de la prise en charge d’un deuil normal et pathologique","contenu":"<p>La <strong>majorité des personnes en deuil n’ont pas besoin de prise en charge médicale</strong> : la <span class=\"kw-def\">phase aiguë</span> du deuil est intense mais se résout progressivement à mesure que la réalité de la perte est intégrée dans la vie quotidienne.</p>\n\n      <p><strong>CAT en consultation — prise en charge de la personne en deuil</strong></p>\n      <ul>\n        <li><span class=\"kw-ttt\">Psychothérapie de soutien</span> et <span class=\"kw-clinique\">écoute empathique</span>.</li>\n        <li><strong>Identifier et expliquer</strong> le processus normal du deuil, notamment en termes de <span class=\"kw-def\">réorganisation</span>.</li>\n        <li><strong>Pas de <span class=\"kw-def\">surmédicalisation</span></strong> du deuil normal : bien distinguer le <span class=\"kw-def\">deuil normal</span> du <span class=\"kw-def\">deuil pathologique</span>.</li>\n        <li>Insister sur l’importance de <strong>partager sa souffrance</strong> (amis, famille, <span class=\"kw-ttt\">associations de soutien</span>…).</li>\n      </ul>\n\n      <div class=\"callout callout-info\"><strong>Deuil prolongé.</strong> Le traitement du <span class=\"kw-etio\">deuil prolongé</span> repose sur une psychothérapie de type <span class=\"kw-ttt\">thérapie comportementale et cognitive (TCC)</span>.</div>\n\n      <p><strong>Accompagnement spécialisé du deuil périnatal</strong></p>\n      <ul>\n        <li><strong>Restaurer le sentiment de compétence parentale</strong>, aussi brève qu’ait été la vie de l’enfant.</li>\n        <li>Proposer un accompagnement du deuil dans une dimension <strong>sociale et associative</strong> (<span class=\"kw-ttt\">groupes de parole</span> entre pairs).</li>\n        <li>Proposer un <strong><span class=\"kw-ttt\">accompagnement social</span></strong> pour <span class=\"kw-clinique\">les</span> démarches administratives (déclaration de décès, congés maternité / paternité, obsèques…).</li>\n        <li>Ouvrir à chacun un <strong>espace individualisé d’expression</strong> de sa souffrance, respectueux du vécu de chacun.</li>\n        <li>Penser à la <strong>fratrie</strong> (exposée à la perte, au chagrin parental, à un sentiment d’abandon et de culpabilité, à l’angoisse de mourir) et aux <strong>grands-parents</strong> (« double peine » : chagrin de la perte de leur petit-enfant + impuissance à protéger leur propre enfant).</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 66 — Trouble dépressif · 140 — Soins palliatifs 2 - accompagnement de la personne et de son entourage · 353 — Risque et conduite suicidaire</em></p>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p><strong>Risque :</strong> le <span class=\"kw-alerte\">risque de suicide</span> est fortement augmenté dans le deuil, <span class=\"kw-alerte\">surtout dans les premiers jours suivant le décès</span> (intention d'« aller rejoindre le défunt »).<br><strong>Fenêtre :</strong> durant la <span class=\"kw-chiffre\">1ʳᵉ semaine</span>, le risque suicidaire est multiplié par <span class=\"kw-chiffre\">&gt; ×50</span> chez l'homme et par <span class=\"kw-chiffre\">×10</span> chez la femme.<br><strong>1er geste :</strong> <span class=\"kw-ttt\">évaluer systématiquement le risque suicidaire</span> et rechercher des <span class=\"kw-alerte\">idées de mort</span> dès <span class=\"kw-clinique\">les</span> consultations précoces.</p>","hospit":"<p><strong>Ambulatoire :</strong> la <span class=\"kw-clinique\">plupart des personnes en deuil n'ont pas besoin de prise en charge médicale</span> ; la phase aiguë intense se résout progressivement.<br><strong>Consultation :</strong> <span class=\"kw-ttt\">psychothérapie de soutien</span> et <span class=\"kw-ttt\">écoute empathique</span> de la personne endeuillée.<br><strong>Orientation spécialisée :</strong> en cas de <span class=\"kw-etio\">deuil pathologique</span> (<span class=\"kw-etio\">deuil prolongé</span>, <span class=\"kw-etio\">épisode dépressif caractérisé</span>) ou de <span class=\"kw-alerte\">risque suicidaire</span> ; <span class=\"kw-ttt\">accompagnement spécialisé</span> dédié dans le <span class=\"kw-etio\">deuil périnatal</span>.</p>","redflags":"<ul><li><span class=\"kw-alerte\">Idées de suicide</span> avec désir de « rejoindre le défunt », surtout dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">premiers jours</span> suivant le décès</li><li>Persistance des symptômes <span class=\"kw-chiffre\">≥ 12 mois</span> (adulte) ou <span class=\"kw-chiffre\">&gt; 6 mois</span> (enfant) sans <span class=\"kw-clinique\">évolution</span> vers la réorganisation</li><li><span class=\"kw-alerte\">Limitation du fonctionnement social</span> et <span class=\"kw-alerte\">incapacité fonctionnelle importante</span></li><li><span class=\"kw-clinique\">Difficulté marquée à accepter le décès</span>, <span class=\"kw-clinique\">incrédulité par rapport à la perte</span>, <span class=\"kw-clinique\">évitement</span> de tout ce qui rappelle la perte</li><li><span class=\"kw-alerte\">Sentiment que la vie n'a plus de sens</span>, <span class=\"kw-alerte\">désir de mourir afin d'être avec le défunt</span></li><li>Signes d'<span class=\"kw-etio\">épisode dépressif caractérisé</span> : <span class=\"kw-clinique\">douleur morale majeure et persistante</span>, <span class=\"kw-clinique\">anhédonie</span>, <span class=\"kw-clinique\">dévalorisation et dégoût de soi</span></li><li>Décès <span class=\"kw-alerte\">brutal</span> (caractère traumatique) faisant craindre un <span class=\"kw-etio\">TSPT</span></li></ul>","principes":"<p>La prise en charge repose sur la distinction entre <span class=\"kw-def\">deuil normal</span> et <span class=\"kw-etio\">deuil pathologique</span>.</p><p><strong>Deuil normal</strong></p><p><span class=\"kw-ci\">Pas de surmédicalisation du deuil normal</span> : bien le distinguer du deuil pathologique.</p><ul><li><span class=\"kw-ttt\">Psychothérapie de soutien</span> et <span class=\"kw-ttt\">écoute empathique</span></li><li><span class=\"kw-ttt\">Identifier et expliquer le processus normal du deuil</span>, notamment en termes de réorganisation</li><li><span class=\"kw-ttt\">Insister sur l'importance de partager sa souffrance</span> (amis, famille, <span class=\"kw-ttt\">associations de soutien</span>)</li></ul><p><strong>Deuil prolongé</strong></p><p>Traitement par <span class=\"kw-ttt\">thérapie comportementale et cognitive</span> (TCC).</p><ul><li><span class=\"kw-etio\">Non-évolution</span> du processus de deuil vers la phase de réorganisation après <span class=\"kw-chiffre\">≥ 12 mois</span></li><li><span class=\"kw-clinique\">Symptômes présents pratiquement tous les jours</span> avec <span class=\"kw-alerte\">incapacité fonctionnelle importante</span></li></ul><p><strong>Épisode dépressif caractérisé</strong></p><p>Prise en charge identique à celle d'un <span class=\"kw-etio\">épisode dépressif caractérisé</span> hors contexte de deuil.</p><ul><li>Trouble psychiatrique le <span class=\"kw-etio\">plus fréquent en contexte de deuil</span></li><li><span class=\"kw-clinique\">Même pronostic, même durée, mêmes comorbidités et même réponse aux traitements</span> qu'un EDC hors deuil</li></ul><p><strong>Deuil périnatal</strong></p><ul><li><span class=\"kw-ttt\">Restaurer le sentiment de compétence parentale</span> des parents</li><li><span class=\"kw-ttt\">Groupes de parole entre pairs</span> et accompagnement associatif</li><li><span class=\"kw-ttt\">Accompagnement social</span> pour <span class=\"kw-clinique\">les</span> démarches administratives (déclaration de décès, congés, obsèques)</li></ul>","suivi":"<p><strong><span class=\"kw-clinique\">Évolution</span> attendue :</strong> le <span class=\"kw-def\">deuil normal</span> est un <span class=\"kw-def\">processus évoluant vers l'apaisement</span>, durant en moyenne <span class=\"kw-chiffre\">2 à 3 mois</span> (selon le lien d'attachement, l'âge du défunt et <span class=\"kw-clinique\">les</span> circonstances du décès).<br><strong>Surveiller :</strong> l'émergence d'un <span class=\"kw-etio\">épisode dépressif caractérisé</span>, d'un <span class=\"kw-etio\">trouble anxieux</span> ou d'un <span class=\"kw-etio\">TSPT</span>, et la réapparition d'<span class=\"kw-alerte\">idées suicidaires</span>.<br><strong>Seuil pathologique :</strong> une persistance <span class=\"kw-chiffre\">&gt; 12 mois</span> (adulte) / <span class=\"kw-chiffre\">&gt; 6 mois</span> (enfant) doit faire évoquer un <span class=\"kw-etio\">deuil prolongé</span>.</p>"},"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Personne en deuil — consultation — Réaction au décès d'un proche","detail":"<h4>CAT — Deuil normal et pathologique — Orientation devant une personne endeuillée</h4>","branches":[{"to":"q-suicide","label":"Évaluation initiale","color":"blue"}]},{"id":"q-suicide","kind":"decision","label":"Risque suicidaire ? — Idées de mort, désir de rejoindre le défunt","branches":[{"to":"t-urgence","label":"Oui","color":"red"},{"to":"q-duree","label":"Non","color":"green"}]},{"id":"t-urgence","kind":"terminal","label":"Évaluation urgente du risque suicidaire","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-alerte\">Idées de suicide</span> avec intention d'« aller rejoindre le défunt »</li><li>Risque maximal dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">premiers jours</span> / la <span class=\"kw-chiffre\">1ʳᵉ semaine</span> (×50 chez l'homme)</li></ul><h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Évaluation du risque suicidaire</span> et orientation psychiatrique urgente</li></ul>"},{"id":"q-duree","kind":"decision","label":"Persistance ≥ 12 mois avec incapacité fonctionnelle ? — Symptômes quasi quotidiens","branches":[{"to":"t-prolonge","label":"Oui","color":"amber"},{"to":"q-edc","label":"Non","color":"green"}]},{"id":"t-prolonge","kind":"terminal","label":"Deuil prolongé","color":"amber","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Difficulté marquée à accepter le décès</span>, <span class=\"kw-clinique\">incrédulité</span>, <span class=\"kw-clinique\">évitement</span></li><li><span class=\"kw-alerte\">Limitation du fonctionnement social</span> et <span class=\"kw-alerte\">incapacité fonctionnelle importante</span></li></ul><h4>Délai</h4><ul><li>Adulte : <span class=\"kw-chiffre\">&gt; 12 mois</span> · Enfant : <span class=\"kw-chiffre\">&gt; 6 mois</span></li><li>Symptômes présents <span class=\"kw-chiffre\">pratiquement tous les jours</span></li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Thérapie comportementale et cognitive</span> (TCC)</li></ul>"},{"id":"q-edc","kind":"decision","label":"Tableau d'épisode dépressif caractérisé ? — Humeur dépressive persistante, anhédonie, dévalorisation","branches":[{"to":"t-edc","label":"Oui","color":"amber"},{"to":"t-normal","label":"Non","color":"green"}]},{"id":"t-edc","kind":"terminal","label":"EDC en contexte de deuil","color":"amber","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Humeur dépressive persistante</span>, <span class=\"kw-clinique\">anhédonie</span></li><li><span class=\"kw-clinique\">Dévalorisation et dégoût de soi</span>, <span class=\"kw-clinique\">douleur morale majeure et persistante</span></li></ul><h4>Conduite</h4><ul><li>Prise en charge identique à un <span class=\"kw-etio\">épisode dépressif caractérisé</span> hors deuil (<span class=\"kw-clinique\">même réponse aux traitements</span>)</li></ul>"},{"id":"t-normal","kind":"terminal","label":"Deuil normal — accompagnement","color":"green","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Psychothérapie de soutien</span> et <span class=\"kw-ttt\">écoute empathique</span></li><li><span class=\"kw-ttt\">Expliquer le processus normal du deuil</span> et <span class=\"kw-ttt\">encourager le partage de la souffrance</span></li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-ci\">Pas de surmédicalisation</span> ; <span class=\"kw-clinique\">évolution</span> vers l'apaisement en <span class=\"kw-chiffre\">2 à 3 mois</span></li></ul>"}]},"cards":[]};